<?php

declare(strict_types=1);
require __DIR__.'/../app/bootstrap.php';

use EventMenu\Core\Database;
use EventMenu\Core\Security;
use EventMenu\Services\CheckoutService;
use EventMenu\Services\PublicOrderPaymentService;
use EventMenu\Services\TenantBrandService;

$pdo=Database::connection();
$token=trim((string)($_GET['t']??''));
$error=null;

function ep_money(int $c):string{return 'R$ '.number_format($c/100,2,',','.');}
function ep_dt(?string $v):string{$t=$v?strtotime($v):false;return $t?date('d/m/Y · H:i',$t):'';}
function ep_friendly_error(Throwable $e):string{$m=trim($e->getMessage());if($m==='')return'Não foi possível iniciar o pagamento. Tente novamente.';if(preg_match('/sql|sqlite|mysql|pdo|http\s*\d|json|exception|database|stack|webhook|endpoint/iu',$m))return'Não foi possível iniciar o pagamento. Tente novamente.';return mb_substr($m,0,200);}
function ep_status(string $s):string{return match(strtolower($s)){'reserved'=>'Aguardando pagamento','paid'=>'Válido','checked_in'=>'Utilizado','cancelled'=>'Cancelado','refunded'=>'Estornado',default=>'Indisponível'};}
function ep_color(mixed $v,string $fallback):string{$v=strtolower(trim((string)$v));return preg_match('/^#[0-9a-f]{6}$/',$v)?$v:$fallback;}
function ep_allowed_checkout_url(string $provider,string $url):bool{$p=parse_url($url);if(($p['scheme']??'')!=='https'||empty($p['host']))return false;$h=strtolower($p['host']);$allowed=['stripe'=>['stripe.com']];foreach($allowed[$provider]??[]as$suffix)if($h===$suffix||str_ends_with($h,'.'.$suffix))return true;return false;}

$paymentService=new PublicOrderPaymentService();
try{$order=$paymentService->order($pdo,$token);}catch(Throwable){$order=null;}
if(!$order||(string)$order['channel']!=='event'){http_response_code(404);exit('Compra de ingresso não encontrada.');}

if($_SERVER['REQUEST_METHOD']==='POST'&&isset($_POST['legacy_provider'])){
    if(!Security::validateCsrf($_POST['_csrf']??null))$error='A página expirou. Atualize e tente novamente.';
    else{try{$provider=(string)$_POST['legacy_provider'];if($provider!=='stripe')throw new RuntimeException('Forma de pagamento indisponível.');$checkout=(new CheckoutService())->create($token,$provider);if(!ep_allowed_checkout_url($checkout['provider'],$checkout['url']))throw new RuntimeException('Não foi possível abrir o pagamento com segurança.');header('Location: '.$checkout['url'],true,303);exit;}catch(Throwable$e){$error=ep_friendly_error($e);}}
}

$tq=$pdo->prepare('SELECT t.*,e.name event_name,e.public_subtitle,e.starts_at,e.ends_at,e.venue,e.address,e.banner_url,e.primary_color,e.secondary_color,e.text_color,e.status event_status,b.name batch_name,b.price_cents,tt.name ticket_type_name,tt.access_area FROM tickets t JOIN events e ON e.id=t.event_id JOIN ticket_batches b ON b.id=t.batch_id LEFT JOIN ticket_types tt ON tt.id=b.ticket_type_id WHERE t.order_id=? AND t.tenant_id=? ORDER BY t.id');
$tq->execute([(int)$order['id'],(int)$order['tenant_id']]);
$tickets=$tq->fetchAll();
if(!$tickets){http_response_code(404);exit('Ingressos não encontrados para esta compra.');}
$event=$tickets[0];

$brandService=new TenantBrandService();
$tenantBrand=$brandService->get((int)$order['tenant_id']);
$visual=(bool)$tenantBrand['apply_web']?$tenantBrand:$brandService->defaults();
$brandName=trim((string)$tenantBrand['display_name'])?:'EventMenu';
$logo=(bool)$tenantBrand['apply_web']?trim((string)$tenantBrand['logo_url']):'';
$primary=ep_color($event['primary_color']??'',(string)$visual['primary_color']);
$secondary=ep_color($event['secondary_color']??'',(string)$visual['secondary_color']);
$background=(string)$visual['background_color'];
$surface=(string)$visual['surface_color'];
$text=ep_color($event['text_color']??'',(string)$visual['text_color']);
$banner=trim((string)($event['banner_url']??''));

try{$paymentMethods=$paymentService->methods($pdo,$token);$paymentProfile=$paymentService->currentProfile($pdo,$token);}catch(Throwable$e){$paymentMethods=['pix'=>[],'card'=>[],'cash'=>false];$paymentProfile=['email'=>'','document_configured'=>false,'document_masked'=>''];if($error===null)$error=ep_friendly_error($e);}
$pixProvider=(string)($paymentMethods['pix'][0]['provider']??'');
$cardMethod=$paymentMethods['card'][0]??null;
$cardTypes=is_array($cardMethod)?(array)($cardMethod['payment_types']??[]):[];
$hasNativePayment=$pixProvider!==''||is_array($cardMethod);
$legacyStripe=$pdo->prepare('SELECT 1 FROM payment_gateways WHERE tenant_id=? AND active=1 AND provider="stripe" LIMIT 1');
$legacyStripe->execute([(int)$order['tenant_id']]);
$legacyStripeEnabled=(bool)$legacyStripe->fetchColumn();

$paid=(string)$order['payment_status']==='paid';
$cancelled=(string)$order['status']==='cancelled';
$reservedUntil=null;
foreach($tickets as$t){if(!empty($t['reserved_until'])&&($reservedUntil===null||strtotime($t['reserved_until'])<strtotime($reservedUntil)))$reservedUntil=$t['reserved_until'];}
$customer=trim((string)($order['customer_name']??''))?:'Cliente';
$csrf=Security::csrfToken();
header('X-Robots-Tag: noindex, nofollow, noarchive');
?>
<!doctype html>
<html lang="pt-BR">
<head>
<meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1,viewport-fit=cover"><meta name="theme-color" content="<?= Security::e($primary) ?>"><meta name="robots" content="noindex,nofollow,noarchive"><meta http-equiv="Cache-Control" content="no-store"><meta name="referrer" content="no-referrer">
<title><?= $paid?'Seus ingressos':'Sua reserva' ?> — <?= Security::e($event['event_name']) ?></title>
<style>
:root{--primary:<?=Security::e($primary)?>;--secondary:<?=Security::e($secondary)?>;--bg:<?=Security::e($background)?>;--surface:<?=Security::e($surface)?>;--text:<?=Security::e($text)?>;--muted:color-mix(in srgb,var(--text) 62%,transparent);--line:color-mix(in srgb,var(--text) 12%,transparent);--soft:color-mix(in srgb,var(--primary) 9%,var(--surface));--shadow:0 18px 50px rgba(35,24,62,.10)}*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--text);font-family:Inter,ui-sans-serif,system-ui,-apple-system,"Segoe UI",sans-serif}.shell{width:min(920px,100%);margin:auto;padding:16px 16px 64px}.top{display:flex;align-items:center;justify-content:space-between;gap:12px;padding:6px 2px 14px}.brand{display:flex;align-items:center;gap:10px}.logo,.mark{width:42px;height:42px;border-radius:12px}.logo{object-fit:cover}.mark{display:grid;place-items:center;background:var(--primary);color:#fff;font-weight:950}.brand strong{font-size:17px}.secure{font-size:12px;color:var(--muted)}.hero{min-height:280px;border-radius:26px;overflow:hidden;position:relative;display:flex;align-items:flex-end;background:linear-gradient(135deg,var(--secondary),var(--primary));box-shadow:var(--shadow)}.hero.has-banner{background-size:cover;background-position:center}.hero:after{content:"";position:absolute;inset:0;background:linear-gradient(180deg,rgba(15,10,35,.08),rgba(15,10,35,.84))}.hero-body{position:relative;z-index:1;padding:30px;color:#fff}.eyebrow{font-size:11px;letter-spacing:.14em;text-transform:uppercase;font-weight:900;opacity:.85}.hero h1{font-size:clamp(32px,7vw,58px);line-height:1;margin:7px 0 10px;letter-spacing:-1.5px}.hero p{margin:0 0 10px;max-width:660px}.meta{display:flex;gap:7px;flex-wrap:wrap}.meta span{font-size:12px;border:1px solid rgba(255,255,255,.24);background:rgba(255,255,255,.12);padding:7px 9px;border-radius:999px}.state{display:flex;justify-content:space-between;gap:16px;align-items:center;background:var(--surface);border:1px solid var(--line);border-radius:18px;padding:18px;margin-top:14px}.state h2{margin:3px 0 5px;font-size:25px}.state p{margin:0;color:var(--muted)}.pill{display:inline-flex;padding:8px 11px;border-radius:999px;background:#fff4d8;color:#805c08;font-size:12px;font-weight:900}.pill.paid{background:#e9f8ef;color:#17623a}.content{display:grid;grid-template-columns:minmax(0,1.2fr) minmax(260px,.6fr);gap:14px;margin-top:14px}.card{background:var(--surface);border:1px solid var(--line);border-radius:18px;padding:20px;box-shadow:0 9px 25px rgba(35,24,62,.04)}.card h2{margin:0 0 6px}.muted{color:var(--muted)}.ticket-list{display:grid;gap:10px;margin-top:14px}.ticket{display:flex;justify-content:space-between;align-items:center;gap:12px;border:1px solid var(--line);border-radius:14px;padding:14px;background:var(--surface)}.ticket strong{display:block}.ticket small{color:var(--muted)}.ticket a{background:var(--primary);color:#fff;text-decoration:none;padding:10px 12px;border-radius:10px;font-weight:900;font-size:12px;white-space:nowrap}.summary-row{display:flex;justify-content:space-between;gap:12px;padding:9px 0;border-bottom:1px solid var(--line)}.summary-row.total{font-size:20px;font-weight:950;border-bottom:0}.alert{padding:13px 14px;border-radius:12px;margin:12px 0;background:#fff5dc;color:#6f520c}.alert.ok{background:#eaf8ef;color:#17623a}.alert.error{background:#fff0f1;color:#963742}.pay{display:grid;gap:12px;margin-top:12px}.pay-method{border:1px solid var(--line);border-radius:15px;padding:15px}.pay-method h3{margin:0 0 5px}.pay-method p{margin:0 0 12px;color:var(--muted);font-size:13px}.grid{display:grid;grid-template-columns:1fr 1fr;gap:9px}.pay label{display:grid;gap:4px;font-size:12px;font-weight:850}.pay input,.pay select{width:100%;padding:11px;border:1px solid var(--line);border-radius:10px;background:#fff}.pay button{border:0;border-radius:10px;padding:11px 14px;font-weight:900;cursor:pointer}.primary{background:var(--primary);color:#fff}.secondary{background:var(--soft);color:var(--primary)}.feedback{display:none;padding:11px;border-radius:10px;background:var(--soft);font-weight:750}.feedback.show{display:block}.feedback.error{background:#fff0f1;color:#963742}.feedback.ok{background:#eaf8ef;color:#17623a}.pix-result{display:none;text-align:center;gap:9px}.pix-result.show{display:grid}.pix-result img{max-width:240px;width:100%;margin:auto}.pix-code{word-break:break-all;text-align:left;padding:10px;background:#f7f6fa;border-radius:9px;font-size:12px}.mp-field{min-height:45px;border:1px solid var(--line);border-radius:10px;background:#fff;padding:2px 8px}.card-types{display:flex;gap:7px;margin-bottom:9px}.card-types label{display:flex;align-items:center;gap:5px;background:var(--soft);padding:7px 9px;border-radius:999px}.card-types input{width:auto}.foot{text-align:center;color:var(--muted);font-size:11px;padding:22px}.countdown{font-weight:900;color:var(--primary)}
@media(max-width:760px){.content{grid-template-columns:1fr}.state{align-items:flex-start;flex-direction:column}.grid{grid-template-columns:1fr}.hero{min-height:330px}.hero-body{padding:24px}.ticket{align-items:flex-start;flex-direction:column}.ticket a{width:100%;text-align:center}.secure{display:none}.shell{padding:10px 10px 50px}.card{padding:16px}}
</style>
<?php if(is_array($cardMethod)):?><script src="https://sdk.mercadopago.com/js/v2"></script><?php endif;?>
</head>
<body>
<main class="shell">
<header class="top"><div class="brand"><?php if($logo!==''):?><img class="logo" src="<?=Security::e($logo)?>" alt="Logo"><?php else:?><div class="mark"><?=Security::e(mb_strtoupper(mb_substr($brandName,0,1)))?></div><?php endif;?><strong><?=Security::e($brandName)?></strong></div><span class="secure">🔒 Compra de ingresso protegida</span></header>
<section class="hero<?= $banner!==''?' has-banner':'' ?>"<?php if($banner!==''):?> style="background-image:url('<?=Security::e($banner)?>')"<?php endif;?>><div class="hero-body"><span class="eyebrow">Seu evento</span><h1><?=Security::e($event['event_name'])?></h1><?php if(trim((string)$event['public_subtitle'])!==''):?><p><?=Security::e($event['public_subtitle'])?></p><?php endif;?><div class="meta"><span><?=Security::e(ep_dt($event['starts_at']))?></span><?php if($event['venue']):?><span><?=Security::e($event['venue'])?></span><?php endif;?><?php if($event['address']):?><span><?=Security::e($event['address'])?></span><?php endif;?></div></div></section>
<section class="state"><div><span class="eyebrow"><?= $paid?'COMPRA CONFIRMADA':'RESERVA DE INGRESSOS' ?></span><h2><?= $paid?'Seus ingressos estão prontos':'Finalize o pagamento' ?></h2><p><?= $paid?'Abra cada ingresso e salve no celular.':'Olá, '.Security::e($customer).'. Seus ingressos ficam reservados enquanto o pagamento estiver disponível.' ?></p><?php if(!$paid&&!$cancelled&&$reservedUntil):?><p style="margin-top:7px">Reserva até <span class="countdown" data-reserved-until="<?=Security::e($reservedUntil)?>"><?=Security::e(ep_dt($reservedUntil))?></span></p><?php endif;?></div><span class="pill<?= $paid?' paid':'' ?>"><?= $paid?'✓ Pagamento confirmado':($cancelled?'Reserva encerrada':'Aguardando pagamento') ?></span></section>
<?php if($error):?><div class="alert error"><?=Security::e($error)?></div><?php endif;?>
<div class="content"><section class="card"><h2><?= $paid?'Seus ingressos':'Ingressos reservados' ?></h2><p class="muted"><?= count($tickets) ?> ingresso(s) individual(is). Cada ingresso possui seu próprio código de acesso.</p><div class="ticket-list"><?php foreach($tickets as$t):$url=app_url('ingresso.php?t='.rawurlencode((string)$t['qr_token']));?><div class="ticket"><div><strong><?=Security::e($t['ticket_type_name']?:'Ingresso')?> · <?=Security::e($t['batch_name'])?></strong><small><?=Security::e($t['code'])?> · <?=Security::e(ep_status((string)$t['status']))?></small></div><?php if($paid||in_array((string)$t['status'],['paid','checked_in'],true)):?><a href="<?=Security::e($url)?>">Abrir ingresso</a><?php else:?><span class="pill">Aguardando</span><?php endif;?></div><?php endforeach;?></div>
<?php if($cancelled):?><div class="alert error">Esta reserva foi encerrada. Se houve débito confirmado pelo provedor, entre em contato com o estabelecimento para conciliação.</div><?php elseif($paid):?><div class="alert ok">✓ Pagamento confirmado. O QR de cada ingresso está disponível individualmente.</div><?php elseif((int)$order['total_cents']>0):?><h2 style="margin-top:22px">Pagamento</h2><?php if($hasNativePayment):?><div class="pay" id="payment-area"><div class="pay-method"><h3>Dados do pagador</h3><p>Use um e-mail e CPF/CNPJ válidos para o pagamento.</p><div class="grid"><label>E-mail<input id="payer-email" type="email" autocomplete="email" value="<?=Security::e((string)($paymentProfile['email']??''))?>"></label><label>CPF/CNPJ<input id="payer-document" inputmode="numeric" maxlength="18" placeholder="<?=$paymentProfile['document_configured']?Security::e((string)$paymentProfile['document_masked']):'Somente números'?>"></label></div></div>
<?php if($pixProvider!==''):?><div class="pay-method"><h3>PIX</h3><p>O QR Code e o Copia e Cola aparecem aqui. A confirmação é automática.</p><button class="primary" type="button" id="generate-pix">Gerar PIX</button><div class="pix-result" id="pix-result"><img id="pix-image" alt="QR Code PIX" hidden><div class="pix-code" id="pix-code"></div><button class="secondary" type="button" id="copy-pix">Copiar PIX</button><small id="pix-expiry"></small></div></div><?php endif;?>
<?php if(is_array($cardMethod)):?><div class="pay-method"><h3>Cartão</h3><p>Os dados sensíveis são tokenizados pelo SDK do Mercado Pago.</p><form id="form-checkout"><div class="card-types"><?php if(in_array('credit_card',$cardTypes,true)):?><label><input type="radio" name="eventmenu-card-type" value="credit_card" checked> Crédito</label><?php endif;?><?php if(in_array('debit_card',$cardTypes,true)):?><label><input type="radio" name="eventmenu-card-type" value="debit_card" <?=!in_array('credit_card',$cardTypes,true)?'checked':''?>> Débito</label><?php endif;?></div><div class="grid"><label>Número<div id="form-checkout__cardNumber" class="mp-field"></div></label><label>Nome no cartão<input id="form-checkout__cardholderName" type="text" autocomplete="cc-name"></label><label>Validade<div id="form-checkout__expirationDate" class="mp-field"></div></label><label>CVV<div id="form-checkout__securityCode" class="mp-field"></div></label><label>Banco<select id="form-checkout__issuer"></select></label><label>Parcelas<select id="form-checkout__installments"></select></label><label>Tipo documento<select id="form-checkout__identificationType"></select></label><label>Documento<input id="form-checkout__identificationNumber" inputmode="numeric"></label><label style="grid-column:1/-1">E-mail<input id="form-checkout__cardholderEmail" type="email" value="<?=Security::e((string)($paymentProfile['email']??''))?>"></label></div><button class="primary" style="margin-top:11px" id="card-submit" type="submit">Pagar com cartão</button></form></div><?php endif;?><div class="feedback" id="payment-feedback" role="status"></div></div><?php endif;?>
<?php if($legacyStripeEnabled):?><div class="pay-method" style="margin-top:12px"><h3>Pagamento online</h3><form method="post"><input type="hidden" name="_csrf" value="<?=Security::e($csrf)?>"><input type="hidden" name="legacy_provider" value="stripe"><button class="secondary" type="submit">Pagar com Stripe</button></form></div><?php endif;?>
<?php if(!$hasNativePayment&&!$legacyStripeEnabled):?><div class="alert">O pagamento online não está disponível para este evento. Entre em contato com <?=Security::e($brandName)?>.</div><?php endif;?><?php endif;?></section>
<aside class="card"><span class="eyebrow">RESUMO FINANCEIRO</span><h2>Compra #<?=(int)$order['id']?></h2><div class="summary-row"><span>Ingressos</span><strong><?=count($tickets)?></strong></div><?php if((int)($order['discount_cents']??0)>0):?><div class="summary-row"><span>Desconto</span><strong>− <?=ep_money((int)$order['discount_cents'])?></strong></div><?php endif;?><div class="summary-row total"><span>Total</span><span><?=ep_money((int)$order['total_cents'])?></span></div><p class="muted" style="font-size:12px">O número da compra é apenas referência financeira. Na entrada, utilize o QR individual do ingresso.</p></aside></div>
<div class="foot">Tecnologia EventMenu</div>
</main>
<?php if(!$paid&&!$cancelled&&$hasNativePayment):?><script>
(()=>{'use strict';const endpoint=<?=json_encode(app_url('api-order-payment.php'),JSON_UNESCAPED_SLASHES)?>,orderToken=<?=json_encode($token)?>,csrf=<?=json_encode($csrf)?>,configuredDocument=<?=$paymentProfile['document_configured']?'true':'false'?>,feedback=document.getElementById('payment-feedback');let polling=null;function show(m,t=''){if(!feedback)return;feedback.className='feedback show'+(t?' '+t:'');feedback.textContent=m}function digits(v){return String(v||'').replace(/\D+/g,'')}async function parse(r){let d;try{d=await r.json()}catch(_){throw new Error('Resposta inválida do servidor.')}if(!r.ok||d?.ok===false)throw new Error(d?.message||'Não foi possível concluir.');return d}async function post(action,payload={}){return parse(await fetch(endpoint+'?action='+encodeURIComponent(action),{method:'POST',credentials:'same-origin',cache:'no-store',headers:{'Content-Type':'application/json','Accept':'application/json','X-CSRF-Token':csrf},body:JSON.stringify({t:orderToken,_csrf:csrf,...payload})}))}async function savePayer(email,document,required=true){email=String(email||'').trim();document=digits(document);if(!email.includes('@'))throw new Error('Informe um e-mail válido.');if(document.length===11||document.length===14)return (await post('profile',{email,document})).profile;if(required||!configuredDocument)throw new Error('Informe CPF ou CNPJ válido do pagador.')}async function status(){const d=await parse(await fetch(endpoint+'?action=status&t='+encodeURIComponent(orderToken),{credentials:'same-origin',cache:'no-store',headers:{Accept:'application/json'}}));if(String(d.payment?.payment_status||'').toLowerCase()==='paid'){clearInterval(polling);show('Pagamento confirmado. Liberando seus ingressos…','ok');setTimeout(()=>location.reload(),600);return true}return false}function startPolling(){clearInterval(polling);status().catch(()=>{});polling=setInterval(()=>status().catch(()=>{}),5000)}
const pix=document.getElementById('generate-pix');if(pix)pix.addEventListener('click',async()=>{pix.disabled=true;try{const email=document.getElementById('payer-email')?.value||'',doc=document.getElementById('payer-document')?.value||'';if(digits(doc).length||!configuredDocument)await savePayer(email,doc,!configuredDocument);else if(!String(email).includes('@'))throw new Error('Informe um e-mail válido.');show('Gerando PIX…');const result=await post('pix',{provider:<?=json_encode($pixProvider)?>}),p=result.payment||{},code=String(p.copy_paste||'');if(!code)throw new Error('O provedor não retornou o PIX Copia e Cola.');document.getElementById('pix-code').textContent=code;const img=document.getElementById('pix-image');if(img&&p.image_url){img.src=p.image_url;img.hidden=false}if(p.expires_at)document.getElementById('pix-expiry').textContent='Válido até '+p.expires_at;document.getElementById('pix-result')?.classList.add('show');show('PIX criado. A confirmação será automática.','ok');startPolling()}catch(e){show(e.message||'Não foi possível gerar o PIX.','error')}finally{pix.disabled=false}});document.getElementById('copy-pix')?.addEventListener('click',async()=>{const c=document.getElementById('pix-code')?.textContent||'';if(!c)return;try{await navigator.clipboard.writeText(c);show('Código PIX copiado.','ok')}catch(_){show('Copie o código PIX exibido acima.')}});
<?php if(is_array($cardMethod)):?>const form=document.getElementById('form-checkout');if(form&&window.MercadoPago){const mp=new MercadoPago(<?=json_encode((string)$cardMethod['public_key'])?>,{locale:'pt-BR'});const cardForm=mp.cardForm({amount:<?=json_encode(number_format(((int)$order['total_cents'])/100,2,'.',''))?>,iframe:true,form:{id:'form-checkout',cardNumber:{id:'form-checkout__cardNumber'},expirationDate:{id:'form-checkout__expirationDate'},securityCode:{id:'form-checkout__securityCode'},cardholderName:{id:'form-checkout__cardholderName'},issuer:{id:'form-checkout__issuer'},installments:{id:'form-checkout__installments'},identificationType:{id:'form-checkout__identificationType'},identificationNumber:{id:'form-checkout__identificationNumber'},cardholderEmail:{id:'form-checkout__cardholderEmail'}},callbacks:{onSubmit:async ev=>{ev.preventDefault();const btn=document.getElementById('card-submit');btn.disabled=true;try{const data=cardForm.getCardFormData(),selected=document.querySelector('input[name="eventmenu-card-type"]:checked')?.value||'credit_card',email=String(data.cardholderEmail||'').trim(),doc=digits(data.identificationNumber||'');await savePayer(email,doc,true);show('Processando cartão…');await post('card',{provider:'mercadopago',token:data.token,payment_method_id:data.paymentMethodId,issuer_id:data.issuerId,installments:Number(data.installments||1),payment_type_id:selected,identification_type:data.identificationType,identification_number:doc,email});show('Pagamento enviado. Confirmando…','ok');startPolling()}catch(e){show(e.message||'Não foi possível processar o cartão.','error')}finally{btn.disabled=false}}}})}<?php endif;?>
setTimeout(()=>status().catch(()=>{}),1500)})();
</script><?php endif;?>
</body></html>
